from scripts.unit1_story_common import zone,cast
META={
'palace_id':'Z7','palace_name':'Protein Factory','story_title':'The Protein Tailor’s Emergency',
'tagline':'A client’s protein has lost its shape minutes before delivery. Follow one polypeptide from amino-acid pieces to a functioning three-dimensional protein.',
'guide':{'name':'Milo Arden','role':'master protein tailor','visual':'burgundy waistcoat, measuring tape around his neck, silver peptide needle','story_job':'keeps one developing polypeptide visible from its amino-acid sequence through every level of folding'},
'premise':'A custom protein arrives unfolded just before the factory’s midnight shipment. Its function lamp stays dark because the chain no longer has the shape required for its job.',
'mission':'Rebuild the protein with Milo. Identify amino-acid parts, connect them with peptide bonds, follow chain direction, see how sequence and R-group chemistry drive folding, and distinguish all four structural levels before testing what denaturation does.',
'finale':'The rebuilt protein folds, assembles, and switches its function lamp back on. After one final denaturation test, Milo seals the repaired molecule for shipment and you can retrace how sequence became shape and shape became function.',
'estimated_minutes':20,'checkpoint_indices':[1,3,8,13],
'route_orientation':'The factory is a single production line that winds upward through fourteen stations. One polypeptide remains with you the entire time, so every new room changes the same chain instead of introducing an unrelated example.',
'route':[{'scene_index':0,'locus':'Protein Entrance','short':'Protein','floor':'Receiving','symbol':'◆'},{'scene_index':1,'locus':'Amino-Acid Workbench','short':'Amino acid','floor':'Bench 1','symbol':'◇'},{'scene_index':2,'locus':'R-Group Sorting Tank','short':'R groups','floor':'Bench 2','symbol':'R'},{'scene_index':3,'locus':'Peptide-Tie Station','short':'Peptide','floor':'Line 1','symbol':'—'},{'scene_index':4,'locus':'N/C Conveyor','short':'Direction','floor':'Line 2','symbol':'N→C'},{'scene_index':5,'locus':'Sequence Folding Machine','short':'Sequence','floor':'Fold 1','symbol':'123'},{'scene_index':6,'locus':'Function Showroom','short':'Functions','floor':'Showroom','symbol':'⚙'},{'scene_index':7,'locus':'Four-Level Elevator','short':'Levels','floor':'Elevator','symbol':'1–4'},{'scene_index':8,'locus':'Secondary Folding Room','short':'Secondary','floor':'Level 2','symbol':'αβ'},{'scene_index':9,'locus':'Tertiary Interaction Chamber','short':'Tertiary','floor':'Level 3','symbol':'◉'},{'scene_index':10,'locus':'Quaternary Assembly Bay','short':'Quaternary','floor':'Level 4','symbol':'◆◆'},{'scene_index':11,'locus':'Raw Chain Inspection','short':'Chain vs protein','floor':'QA','symbol':'?'},{'scene_index':12,'locus':'Soluble-Protein Water Tank','short':'Water','floor':'QA tank','symbol':'💧'},{'scene_index':13,'locus':'Denaturation Furnace','short':'Denature','floor':'Exit test','symbol':'♨'}]
}
SCENES=[
{'locus':'Protein Entrance','title':'The Protein That Forgot Its Shape','kicker':'A protein is more than a chain; it is a chain organized into a working three-dimensional structure.','location_description':'Receiving doors open onto a circular inspection table. A long molecular chain lies collapsed across it like loose ribbon. A function lamp above the table stays dark. Twenty amino-acid drawers line the back wall.','orientation':'The unfolded chain is centered, the CHON element scanner stands left, and the wall of twenty amino-acid drawers is right.','zones':[zone('left','Element scanner','CHON','Checks the common amino-acid backbone for carbon, hydrogen, oxygen, and nitrogen; sulfur appears only in selected side chains.'),zone('center','Unfolded protein table','◆','Shows that a chain without its native three-dimensional organization may lose function.'),zone('right','Twenty-drawer wall','20','Contains the standard set of twenty amino acids used to build proteins.')],
'cast':[cast('Damaged protein','central object','one long polypeptide collapsed into an unstructured coil','must regain the appropriate three-dimensional organization before its function lamp will turn on'),cast('Amino-acid drawers','building-unit library','twenty distinct drawers with the same backbone stencil but different side-chain symbols','represent the standard set of 20 amino acids used in proteins')],
'paragraphs':['Milo Arden lifts the collapsed chain with both hands. “This is still a polypeptide chain, but the client ordered a working **protein**.” A protein consists of one or more polypeptide chains organized into a specific three-dimensional shape, and that shape is intimately connected with what the protein can do.', 'The scanner flashes C, H, O, and N across the common amino-acid backbone. Those elements are necessarily present in the standard amino-acid framework. A sulfur light appears only on selected side chains, reminding you that sulfur occurs in some amino acids and some proteins, not every protein.', 'Milo opens the wall of **20 amino-acid** drawers. Each drawer contains a different standard amino acid. “Same basic frame,” he says, “different side piece. We rebuild from here.” He rolls the chain to the first workbench.']},
{'locus':'Amino-Acid Workbench','title':'One Backbone, One Variable Side','kicker':'Every amino acid shares a core architecture, while the R group changes.','location_description':'A bright workbench holds one oversized amino-acid model. A central carbon sits in the middle with four attachments: hydrogen above, amino group left, carboxyl group right, and an interchangeable R-group socket below.','orientation':'The amino group is left of the central carbon, the central carbon/hydrogen is center, the carboxyl group is right, and the R-group socket hangs below.','zones':[zone('left','Amino group','NH₂/NH₃⁺','Contributes the nitrogen-containing amino end of the amino-acid framework.'),zone('center','Central carbon','Cα','Connects hydrogen, amino group, carboxyl group, and the variable R group.'),zone('right','Carboxyl group','COOH/COO⁻','Provides the carboxyl end used when peptide bonds form.')],
'cast':[cast('Amino acid','protein building block','a central carbon carrying hydrogen, amino group, carboxyl group, and one variable R group','serves as the building unit from which polypeptide chains are assembled'),cast('R-group socket','variable position','an empty socket below the central carbon','accepts a side chain whose chemical properties distinguish one amino acid from another')],
'paragraphs':['Milo fixes the model under a spotlight. An **amino acid** has a central carbon attached to a hydrogen, a carboxyl group, an amino group, and a variable **R group**. You can picture the first four pieces as the shared chassis and the R group as the replaceable attachment.', 'He rotates the model until the amino group is always on your left and the carboxyl group on your right. The arrangement becomes a stable visual reference for the next station, where R groups are sorted by how they behave.', 'The R-group socket clicks open. Three colored side chains drop into a sorting tank ahead.'] ,'checkpoint_object_id':'MO-APBIO-U1-PF003','checkpoint_prompt':'What are the protein building blocks that contain a central carbon, hydrogen, amino group, carboxyl group, and variable R group?'},
{'locus':'R-Group Sorting Tank','title':'The Side Chains Choose Their Company','kicker':'R groups change amino-acid chemistry, so they strongly influence how a chain will fold.','location_description':'Three transparent tanks stand beneath the workbench. One is filled with oil, one with water, and one with charged magnetic beads. Different R-group models are released above them and sort according to their chemical properties.','orientation':'The nonpolar/oil tank is left, polar/water tank center, and charged-ion tank right.','zones':[zone('left','Nonpolar tank','油','Hydrophobic side chains avoid the surrounding water display.'),zone('center','Polar tank','💧','Polar side chains interact favorably with water.'),zone('right','Charged tank','+/−','Ionic side chains carry positive or negative charge and interact strongly with water and opposite charges.')],
'cast':[cast('R group','variable side chain','the replaceable attachment on each amino acid','determines many of the amino acid’s distinctive chemical properties'),cast('Nonpolar R group','hydrophobic side chain','an oily side chain that withdraws from water','tends to avoid aqueous surroundings'),cast('Polar R group','hydrophilic side chain','a side chain that forms favorable interactions with water','tends to interact with aqueous surroundings'),cast('Ionic R group','charged side chain','a side chain carrying a + or − badge','is generally hydrophilic and can form electrostatic interactions')],
'paragraphs':['Milo drops three side chains at once. The oily one avoids the water region: a **nonpolar R group**, usually hydrophobic. The second mixes comfortably with water: a **polar R group**, usually hydrophilic. The third carries a full charge: an **ionic R group**, also generally hydrophilic because charged groups interact strongly with water.', 'Acidic side chains commonly carry negative charge at cellular pH, while basic side chains commonly carry positive charge. Milo does not ask you to memorize every side chain here. He wants you to see the consequence: changing the **R group** changes what an amino acid can attract, repel, avoid, or bond with.', 'The sorted amino acids drop onto a rail in a precise order. A silver needle waits to connect the carboxyl end of one to the amino end of the next.']},
{'locus':'Peptide-Tie Station','title':'The Stitch That Builds the Chain','kicker':'Amino acids become a polypeptide when peptide bonds connect them in sequence.','location_description':'A tailoring machine lines amino acids from left to right. The carboxyl group of one faces the amino group of the next. A silver needle removes H and OH components as it closes a covalent stitch between them.','orientation':'Separate amino acids enter left, the peptide needle operates center, and the growing polypeptide exits right.','zones':[zone('left','Amino-acid feed','◇◇','Supplies ordered amino acids.'),zone('center','Peptide needle','H₂O out','Forms the covalent peptide connection through a dehydration reaction.'),zone('right','Polypeptide roll','◇—◇—◇','Collects the growing amino-acid chain.')],
'cast':[cast('Peptide bond','covalent connection','a silver stitch between the carboxyl group of one amino acid and amino group of the next','links amino acids into a chain'),cast('Dehydration reaction','bond-forming chemistry','H and OH components leave as the stitch closes','forms the peptide connection while components equivalent to water are removed'),cast('Polypeptide','amino-acid chain','many amino acids joined in one continuous covalent chain','is the linear chain produced by repeated peptide-bond formation')],
'paragraphs':['The needle aligns the carboxyl group of one amino acid with the amino group of the next. The covalent connection that forms is a **peptide bond**. Repeating that connection produces a **polypeptide**, a chain of many amino acids.', 'As each stitch closes, components equivalent to water are removed. Peptide-bond formation is therefore a **dehydration reaction**. The water is not the bond; the new covalent peptide connection is.', 'Milo winds the growing polypeptide onto a conveyor. One end receives a blue N tag and the opposite end a red C tag before the chain moves on.'] ,'checkpoint_object_id':'MO-APBIO-U1-PF009','checkpoint_prompt':'What covalent bond connects amino acids in a polypeptide?'},
{'locus':'N/C Conveyor','title':'The Chain Has a Direction','kicker':'A polypeptide is chemically different at its two ends.','location_description':'A long conveyor carries the new polypeptide through a scanner. The first end is marked N in blue; the far end is marked C in red. The belt moves only from the N-tagged entrance toward the C-tagged exit.','orientation':'N-terminus gate is left, the polypeptide lies across center, and C-terminus gate is right.','zones':[zone('left','N-terminus','N','Marks the amino end of the chain.'),zone('center','Polypeptide conveyor','N→C','Keeps sequence order visible from one chemically distinct end to the other.'),zone('right','C-terminus','C','Marks the carboxyl end of the chain.')],
'cast':[cast('N-terminus','polypeptide end','blue N tag on the amino end','marks one chemically distinct end of the chain'),cast('C-terminus','polypeptide end','red C tag on the carboxyl end','marks the opposite chemically distinct end')],
'paragraphs':['The scanner gives the chain a direction. A polypeptide has two chemically distinct ends: the **N-terminus**, associated with the amino end, and the **C-terminus**, associated with the carboxyl end.', 'Milo keeps the tags attached as the belt moves. Sequence is therefore not just a bag of amino acids; order has direction. Changing which amino acid occurs at a particular position changes the primary structure of the chain.', 'At the end of the conveyor, a coded ribbon marked GENE lowers from the ceiling and begins feeding instructions into the folding machine.']},
{'locus':'Sequence Folding Machine','title':'The Order Becomes a Shape','kicker':'The amino-acid sequence constrains which interactions can form and therefore how the chain folds.','location_description':'A large machine reads a gene-coded tape above the conveyor and arranges amino-acid tiles below it. The resulting chain enters a transparent folding chamber where its R groups begin attracting, repelling, and avoiding water.','orientation':'Gene tape reader is left, ordered amino-acid sequence runs through center, and the transparent folding chamber is right.','zones':[zone('left','Gene tape','DNA','Specifies the order of amino acids in the polypeptide.'),zone('center','Sequence rail','1-2-3','Displays the exact linear amino-acid sequence.'),zone('right','Folding chamber','↺','Allows R-group chemistry to turn sequence into higher-order shape.')],
'cast':[cast('Gene instructions','information source','a coded nucleotide tape feeding an amino-acid selector','specify the amino-acid sequence of the polypeptide'),cast('Amino-acid sequence','primary information','a fixed order of colored amino-acid tiles','determines primary structure and strongly influences the possible folding of the chain'),cast('R-group interactions','folding forces','side chains reaching toward or away from one another','help drive and stabilize the three-dimensional folding pattern')],
'paragraphs':['The gene-coded ribbon controls which amino-acid drawer opens next. **Gene information determines the amino-acid sequence** of the polypeptide. The machine does not choose the sequence after folding; the order comes first.', 'That **sequence determines primary structure** and strongly influences the eventual shape. As the chain enters the chamber, its R groups begin interacting according to their chemistry—hydrophobic groups withdraw from water, charged groups attract or repel, polar groups form favorable interactions.', 'Milo watches the same chain bend. **R-group interactions** help drive and stabilize folding, so changing the sequence can relocate those side chains and alter the final shape.', 'The partly folded chain emerges into a bright showroom filled with protein machines doing different jobs.']},
{'locus':'Function Showroom','title':'Shape Becomes Work','kicker':'Proteins do many jobs, and their shapes allow them to interact with the right partners.','location_description':'A showroom displays six working protein models: an enzyme press, antibody shield, receptor signal bell, structural cable, transport carrier, and storage capsule. The developing protein moves past each station.','orientation':'The catalysis and defense displays line your left, signaling and structural proteins fill the center, and transport and storage proteins occupy your right.','zones':[zone('left','Catalysis and defense','⚙/🛡','Shows enzymes and defensive proteins.'),zone('center','Signaling and structure','🔔/▥','Shows receptor or hormone-related signaling and structural support.'),zone('right','Transport and storage','⇢/▣','Shows proteins that carry or store substances.')],
'cast':[cast('Protein function gallery','functional diversity','six differently shaped molecular machines','demonstrates that proteins can catalyze reactions, defend, signal, support structure, transport, and store; some hormones are proteins')],
'paragraphs':['The showroom turns “protein function” into a set of visible jobs. One folded protein acts as an **enzyme**, accelerating a reaction. Another forms an **antibody-like defense** shape. Others participate in signaling, structural support, transport, and storage. Some hormones are proteins as well.', 'The common lesson is not that every protein performs all of these jobs. It is that proteins are an extraordinarily diverse functional class because different sequences can produce different three-dimensional structures and interaction surfaces.', 'Milo guides your chain into an elevator with four numbered floors. “Now we separate the levels of structure that built that function.”']},
{'locus':'Four-Level Elevator','title':'The Four Floors of Protein Structure','kicker':'The levels are nested: sequence first, then local folding, whole-chain folding, and sometimes multi-chain assembly.','location_description':'A glass elevator has four illuminated floor buttons. Floor 1 displays a straight amino-acid sequence, floor 2 local coils and sheets, floor 3 one fully folded chain, and floor 4 several chains assembled together.','orientation':'Buttons 1 and 2 are left, the developing protein travels in the center elevator, and buttons 3 and 4 are right.','zones':[zone('left','Levels 1–2','1/2','Primary sequence and local backbone folding.'),zone('center','Protein elevator','↑','Carries the same chain upward through increasingly organized structures.'),zone('right','Levels 3–4','3/4','Whole-chain tertiary folding and, where present, multi-chain quaternary assembly.')],
'cast':[cast('Primary structure','level 1','the linear amino-acid sequence laid out as colored beads','is the exact order of amino acids in the polypeptide'),cast('Four structural levels','organization hierarchy','four elevator floors from sequence to multi-subunit assembly','together contribute to the shape and function of proteins')],
'paragraphs':['At floor 1, the chain lies straight so its order is easy to read. **Primary structure** is the linear amino-acid sequence. Because the sequence positions every R group, it influences all higher levels of structure.', 'Milo points up: floor 2 will show local backbone folding, floor 3 the overall three-dimensional shape of one polypeptide, and floor 4 assembly among multiple polypeptide chains when the protein has multiple subunits.', 'All four structural levels contribute to protein function when those levels are present. The elevator opens at floor 2, where the chain is already curling into a spring and folding into a sheet.']},
{'locus':'Secondary Folding Room','title':'Springs and Pleated Sheets','kicker':'Hydrogen bonds in the backbone create local recurring folds.','location_description':'The second floor contains two shaping rigs. On the left, the polypeptide backbone winds around a cylinder into a coil. On the right, neighboring stretches fold back and forth into a pleated sheet. Dotted hydrogen bonds hold both patterns.','orientation':'Alpha-helix rig is left, a backbone-only diagram is center, and beta-sheet rig is right.','zones':[zone('left','Alpha-helix rig','α','Coils one stretch of backbone and stabilizes it with backbone hydrogen bonds.'),zone('center','Backbone map','···','Shows that secondary-structure hydrogen bonds involve the polypeptide backbone.'),zone('right','Beta-sheet rig','β','Aligns neighboring stretches of chain into a pleated sheet stabilized by backbone hydrogen bonds.')],
'cast':[cast('Secondary structure','local folding level','localized coils and sheets forming along the backbone','consists of local backbone folds stabilized largely by hydrogen bonds'),cast('Alpha helix','secondary structure','a spring-like coil with repeated hydrogen bonds','is a coiled secondary structure stabilized by backbone hydrogen bonds'),cast('Beta-pleated sheet','secondary structure','a folded sheet with hydrogen bonds between adjacent stretches','is a sheet-like secondary structure stabilized by backbone hydrogen bonds; it does not require separate polypeptide chains')],
'paragraphs':['The chain enters the coil rig. Hydrogen bonds form repeatedly along the polypeptide backbone, stabilizing a spring-like **alpha helix**. This is one form of **secondary structure**.', 'On the other side, a different stretch folds back and forth. Hydrogen bonds form between nearby stretches of the backbone, creating a **beta-pleated sheet**. The stretches can belong to the same polypeptide; separate chains are not required.', 'Secondary structure is therefore local. Milo highlights the backbone and turns down the R-group colors so you can see that the recurring hydrogen-bond pattern here belongs primarily to the backbone. The elevator opens to floor 3, where every side chain lights up again.'] ,'checkpoint_object_id':'MO-APBIO-U1-PF018','checkpoint_prompt':'What level of protein structure consists of local backbone folds such as alpha helices and beta-pleated sheets?'},
{'locus':'Tertiary Interaction Chamber','title':'The Whole Chain Folds Into One Shape','kicker':'Side-chain chemistry now pulls distant parts of the same polypeptide together.','location_description':'The third floor is a spherical chamber filled with water. The entire polypeptide floats at center while side chains reach across long distances. Hydrophobic groups tuck inward; charged and polar groups interact; two sulfur-containing cysteines can lock together.','orientation':'Hydrophobic collapse display is left, the one-chain folded protein is center, and side-chain interaction controls including a sulfur bridge are right.','zones':[zone('left','Hydrophobic interior','oil','Nonpolar side chains often cluster away from surrounding water.'),zone('center','One folded polypeptide','3D','Shows tertiary structure as the overall shape of one chain.'),zone('right','Interaction panel','+/− ··· S—S','Shows ionic interactions, hydrogen bonds, van der Waals contacts, and disulfide bridges among side chains.')],
'cast':[cast('Tertiary structure','whole-chain fold','one polypeptide folded into a compact three-dimensional form','is the overall 3D structure of one polypeptide produced and stabilized by side-chain interactions'),cast('Disulfide bridge','covalent stabilizer','a strong S—S clasp between two cysteine side chains','is a covalent bond between sulfur atoms of two cysteines that can stabilize tertiary structure')],
'paragraphs':['Now the entire chain folds. This overall three-dimensional shape of one polypeptide is **tertiary structure**. Parts that were far apart in the linear sequence can become neighbors in space.', 'Milo turns on the interaction panel. Hydrophobic side chains cluster away from water; polar groups can form hydrogen bonds; oppositely charged side chains can form ionic attractions; close atoms can contribute van der Waals interactions. These side-chain interactions collectively help stabilize the tertiary fold.', 'Two cysteine side chains approach. Their sulfur atoms form a covalent **disulfide bridge**, a particularly strong clasp that can help stabilize the folded structure.', 'The compact chain now fits perfectly into a docking socket—but the shipment order calls for a protein with multiple subunits. The floor opens into the Quaternary Assembly Bay.']},
{'locus':'Quaternary Assembly Bay','title':'Several Chains Become One Protein Complex','kicker':'Quaternary structure exists only when multiple polypeptide subunits associate.','location_description':'Four folded polypeptide subunits arrive on separate rails and dock around a central ring. Each subunit keeps its own tertiary structure while making new contacts with the others.','orientation':'Individual folded chains wait left, the assembly dock is center, and the completed multi-subunit protein exits right.','zones':[zone('left','Folded subunits','◆ ◆','Each polypeptide arrives already folded.'),zone('center','Assembly dock','◆◆','Subunits associate through compatible surfaces.'),zone('right','Protein complex','◉','The multi-chain assembly functions as one protein complex.')],
'cast':[cast('Quaternary structure','multi-subunit organization','several folded polypeptide chains docking together','arises from interactions among multiple polypeptide subunits and exists only in proteins that contain more than one polypeptide chain')],
'paragraphs':['The first folded chain docks beside a second, then a third and fourth. The organization created by association among multiple polypeptide chains is **quaternary structure**.', 'Milo leaves one empty single-chain model beside the dock as a reminder: a protein made from only one polypeptide has no quaternary level. Quaternary structure exists only when multiple subunits associate.', 'The completed complex passes the assembly test. But before it can leave, quality control asks a deceptively simple question: when is a polypeptide merely a chain, and when is it a functional protein?']},
{'locus':'Raw Chain Inspection','title':'Chain Is Not the Same as Finished Protein','kicker':'The covalent chain is necessary, but functional organization is the finished product.','location_description':'Quality control places two samples under identical lights. The left sample is an extended amino-acid chain. The right sample is one or more chains folded into a stable working structure with an active function lamp.','orientation':'Raw polypeptide is left, inspection scanner center, and functional protein is right.','zones':[zone('left','Raw chain','~~~~','A linear amino-acid chain held together by peptide bonds.'),zone('center','Inspection scanner','?','Checks whether appropriate higher-order organization has formed.'),zone('right','Functional protein','◆','One or more polypeptides folded and organized into a specific 3D structure.')],
'cast':[cast('Polypeptide','covalent chain','a long amino-acid ribbon connected by peptide bonds','is the linear amino-acid chain'),cast('Protein','organized functional molecule','the folded structure whose function lamp is active','consists of one or more polypeptide chains organized into a specific three-dimensional structure')],
'paragraphs':['The left sample is a **polypeptide**: a linear chain of amino acids connected by peptide bonds. That word tells you about the chain itself.', 'The right sample is a **protein**: one or more polypeptide chains folded and organized into a specific three-dimensional structure. Many proteins require that higher-order organization to perform their biological function.', 'Quality control passes the distinction. The protein is then lowered into a water tank to test whether the side chains are arranged sensibly for an aqueous environment.']},
{'locus':'Soluble-Protein Water Tank','title':'Which Side Chains Face the Water?','kicker':'For many soluble proteins, the watery environment helps sort hydrophobic and hydrophilic side chains.','location_description':'A clear tank fills with water around the folded protein. Nonpolar side chains disappear toward the interior while polar and charged groups remain more exposed at the surface. A membrane-protein warning sign hangs above the tank.','orientation':'Water surrounds the protein on all sides, the hydrophobic core is visible at center, and exposed polar/charged groups cover the outer surface.','zones':[zone('left','Aqueous environment','💧','Surrounds the soluble protein.'),zone('center','Hydrophobic core','oil','Often buries nonpolar side chains away from water.'),zone('right','Hydrophilic surface','+/−','Often exposes polar and charged side chains to water.')],
'cast':[cast('Soluble protein','aqueous protein','a compact globular protein suspended in water','often folds with hydrophobic side chains buried and polar or charged side chains exposed'),cast('Membrane-protein warning','context guard','a membrane icon with DO NOT GENERALIZE stamped beside it','reminds you that membrane proteins experience a different chemical environment and may orient side chains differently')],
'paragraphs':['As the protein settles into water, many **nonpolar hydrophobic R groups** become buried in the interior, away from the aqueous environment. Many **polar and charged R groups** remain exposed, where they can interact favorably with water.', 'Milo points to the warning sign. This is a common pattern for **soluble proteins**, not a universal rule for every protein. Membrane proteins live partly in a hydrophobic lipid environment and can organize their side chains differently.', 'The protein survives the water test. One final door opens: a furnace designed to disturb the interactions that keep the protein folded.']},
{'locus':'Denaturation Furnace','title':'When Shape Comes Apart','kicker':'Destroy the stabilizing interactions and function can disappear even if the covalent backbone is not cut apart.','location_description':'A red testing chamber surrounds the protein. Heat and chemical-condition controls rise on the left. The protein’s carefully folded shape begins loosening while the peptide-bond backbone remains visibly connected.','orientation':'Stress controls are left, the unfolding protein is center, and the darkening function lamp is right.','zones':[zone('left','Stress controls','♨','Alter temperature or chemical conditions that stabilize the native structure.'),zone('center','Unfolding protein','~','Higher-order shape is disrupted without automatically hydrolyzing peptide bonds.'),zone('right','Function lamp','OFF','Shows that loss of native shape often causes loss of function.')],
'cast':[cast('Denaturation','loss of native structure','a folded protein opening into a disordered chain while peptide bonds remain intact','occurs when conditions disrupt interactions that stabilize the native 3D structure, often causing loss of function')],
'paragraphs':['The furnace warms. Hydrogen bonds, ionic interactions, hydrophobic organization, and other stabilizing interactions are disturbed. The protein loses its native three-dimensional shape. That loss of native structure is **denaturation**.', 'The function lamp goes dark. Denaturation often causes loss of function because the protein no longer has the shape required for its interactions. Milo highlights the peptide-bond backbone: ordinary denaturation does not mean the chain has been hydrolyzed into individual amino acids.', 'He lowers the stress and closes the chamber. The repaired shipment sits beside the damaged original, and the whole route is visible through the factory glass: amino-acid structure → R-group chemistry → peptide-bonded polypeptide → directed sequence → local folding → whole-chain folding → multi-chain assembly → function.'] ,'checkpoint_object_id':'MO-APBIO-U1-PF028','checkpoint_prompt':'What term describes loss of a protein’s native three-dimensional structure when stabilizing interactions are disrupted?'}
]
